"""Source-linked WB government assignment audit. Never edits evidence_table.csv."""
from pathlib import Path
import collections,csv,datetime,hashlib,json,re
ROOT=Path(__file__).resolve().parent
EVIDENCE=ROOT.parent/'evidence_table.csv'
SOURCES={
 'WB_ASSEMBLY_HISTORY':dict(url='https://lalib.wb.gov.in/showOverview',type='official_state_legislature',locator='1996/2000, 2001, 2006, 2011 overview paragraphs',supports='Left Front governments; Buddhadeb assumption 6 November2000; Mamata/AITC-INC ministry 20 May2011. Coalition component lists are the Assembly historical descriptions, not separately verified minister rosters.'),
 'PARLIAMENT_2000':dict(url='https://eparlib.sansad.in/bitstream/123456789/764740/1/jpi_march_2001.pdf',type='official_parliamentary_journal',locator='Parliamentary and Constitutional Developments, West Bengal, printed page81',supports='Basu resignation reported29 October 2000; Buddhadeb sworn6 November 2000. Use succession date, not earlier resignation announcement, for government change.'),
 'CPIM_BASU':dict(url='https://cpim.org/jyoti-basu/',type='party_primary_biography',supports='Jyoti Basu CPI(M) leadership, Left Front government and21 June 1977 oath; party source used for affiliation, not evaluation of conduct.'),
 'CPIM_BUDDHADEB':dict(url='https://cpim.org/comrade-buddhadeb-bhattacharya/',type='party_primary_obituary',supports='Buddhadeb CPI(M) leadership and Left Front chief ministership; affiliation corroboration, not neutral policy assessment.'),
 'INC_WITHDRAWAL_NEWS':dict(url='https://www.ndtv.com/india-news/congress-ministers-resign-from-west-bengal-government-set-sights-at-cabinet-berths-499943',type='contemporaneous_original_reporting_official_notification_not_found',published='2012-09-22',supports='Six Congress ministers submitted resignations and Congress leaders withdrew support on 22 September 2012. Formal gazette acceptance and intraday boundary not independently recovered.'),
 'PIB_2026_OATH':dict(url='https://www.pib.gov.in/PressReleasePage.aspx?PRID=2259319&lang=1&reg=3',type='official_PMO_PIB_release',published='2026-05-09',supports='Suvendu Adhikari took CM oath9 May 2026; official date anchor. Not a source for every coalition/cabinet detail.'),
 'TOI_2026_PARTY':dict(url='https://timesofindia.indiatimes.com/city/kolkata/journey-from-nandigram-to-writers-buildings-the-political-journey-of-suvendu-adhikari/articleshow/130970520.cms',type='contemporaneous_primary_news',published='2026-05-09',supports='BJP legislature-party leader became first BJP CM. Used for explicit party label alongside official oath release.'),
 'MHA_CAPF':dict(url='https://www.mha.gov.in/en/divisionofmha/police-ii-division',type='official_union_ministry',supports='MHA Police-II Division handles CAPF policy/personnel/operational including deployment/financial matters and lists BSF and CISF.'),
 'MHA_ANNUAL':dict(url='https://www.mha.gov.in/sites/default/files/AnnualreportEnglish_04102023.pdf',type='official_union_ministry_annual_report',locator='paragraph 7.27',supports='BSF, CISF and CRPF are central forces under MHA. Does not establish orders for a particular shooting.'),
 'RPA_28A':dict(url='https://www.indiacode.nic.in/bitstream/123456789/1941/1/195143.pdf',type='official_legislation',locator='Representation of the People Act 1951, section 28A; inserted 1989',supports='Designated election police officers stand deputed to ECI during statutory election period and are subject to its control/superintendence/discipline.'),
 'ECI_FORCE_MANUAL':dict(url='https://www.eci.gov.in/eci-backend/public/api/download?url=LMAhAK6sOPBp%2FNFF0iRfXbEB1EVSLT41NNLRjYNJJP1KivrUxbfqkDatmHy12e%2FzVx8fLfn2ReU7TfrqYobgIvZ0n19tFMJzYNUMlQdr0LR9wv8%2B5nXgMo0aziJ0WKXcD2mjzPfzEgKRfE3Jice0BpSrPmQz9vt2aDMViYDfJ9IM%2F2fqtXgeR74oE38CYbCb',type='official_ECI_manual_2023',locator='section 1.4 and chapter 3',supports='State/central forces on election duty are under ECI election supervision; deployment involves ECI, MHA, state/district functionaries. This 2023 manual is framework evidence, not the specific2021 firing order.'),
}
spells=[
 dict(spell_id='WB_JYOTI_LF',start_ist='1977-06-21',end_exclusive_ist='2000-11-06',chief_minister='Jyoti Basu',cm_party='CPI(M)',government_coalition='CPI(M)-led Left Front',confidence='high_for_catalogue_dates',source_ids=['WB_ASSEMBLY_HISTORY','PARLIAMENT_2000','CPIM_BASU']),
 dict(spell_id='WB_BUDDHADEB_LF',start_ist='2000-11-06',end_exclusive_ist='2011-05-20',chief_minister='Buddhadeb Bhattacharjee',cm_party='CPI(M)',government_coalition='CPI(M)-led Left Front',confidence='high_for_catalogue_dates',source_ids=['WB_ASSEMBLY_HISTORY','PARLIAMENT_2000','CPIM_BUDDHADEB']),
 dict(spell_id='WB_MAMATA_INC',start_ist='2011-05-20',end_exclusive_ist='2012-09-22',chief_minister='Mamata Banerjee',cm_party='AITC',government_coalition='AITC-led government with INC cabinet partner',confidence='high_for_catalogue_dates; withdrawal_day_boundary_news_based',source_ids=['WB_ASSEMBLY_HISTORY','INC_WITHDRAWAL_NEWS']),
 dict(spell_id='WB_MAMATA_WITHDRAWAL_DAY',start_ist='2012-09-22',end_exclusive_ist='2012-09-23',chief_minister='Mamata Banerjee',cm_party='AITC',government_coalition='AITC-led; INC resignation/withdrawal transition day',confidence='do_not_resolve_intraday_coalition_without_gazette_or_time',source_ids=['INC_WITHDRAWAL_NEWS']),
 dict(spell_id='WB_MAMATA_POST_INC',start_ist='2012-09-23',end_exclusive_ist='2026-05-09',chief_minister='Mamata Banerjee',cm_party='AITC',government_coalition='AITC-led majority government; INC no longer cabinet partner',confidence='high_for_catalogue_dates; exact_formal_2012_acceptance_not_recovered',source_ids=['WB_ASSEMBLY_HISTORY','INC_WITHDRAWAL_NEWS','PIB_2026_OATH','TOI_2026_PARTY']),
 dict(spell_id='WB_SUVENDU_BJP',start_ist='2026-05-09',end_exclusive_ist=None,chief_minister='Suvendu Adhikari',cm_party='BJP',government_coalition='BJP-led government',confidence='high_oath_date_official; party_primary_news_corroboration',source_ids=['PIB_2026_OATH','TOI_2026_PARTY']),
]
def get_spell(day):
 return next(s for s in spells if day>=s['start_ist'] and (not s['end_exclusive_ist'] or day<s['end_exclusive_ist']))
institutions={
 'WB_2009_Bandih':('state armed police and CRPF','mixed_state_police_and_Union_MHA_central_force','Not solely a state-force or centrally directed episode; operational orders are not established.'),
 'WB-2010-06-16_17-Salboni-Murmu':('reported police/joint-forces arrest and media display','exact_agency_breakdown_not_resolved_here','Do not infer exact force composition or command from a state-government label.'),
 'WB-2010-08-23-DumDum':('Dum Dum prison officials','state_correctional_administration','Prison custodial conduct, distinct from state-police street operation.'),
 'WB-2011-12-16_17-CoochBehar-BSF':('BSF','Union_MHA_central_force','State party is geographic government context; BSF is not West Bengal state police.'),
 'WB_2019_Dulal':('BSF','Union_MHA_central_force','State party does not identify BSF administrative authority or who ordered firing.'),
 'WB_2020_Kasem':('BSF','Union_MHA_central_force','Central force; state party is not evidence of operational command.'),
 'WB-2021-04-10-Sitalkuchi-CISF':('CISF on election duty','Union_MHA_central_force_with_ECI_election_supervision','ECI election supervision applies; specific on-site firing order and partisan responsibility are not established. Do not automatically assign state-party or Union-party orders.'),
}
rows=[r for r in csv.DictReader(EVIDENCE.open()) if r['state']=='West Bengal'];assignments=[]
for r in rows:
 dates=re.findall(r'\d{4}-\d{2}-\d{2}',r['event_date_ist']);datebasis=r['date_basis'];dateconfidence='use_input_reported_or_inferred_date_basis; not independently reverified here'
 inferred='';alternatives=[]
 if r['case_id']=='WB_2012_Canning':
  d=json.loads((ROOT.parent/'collection/records/11785387.json').read_text())
  assert d['publication_date'].startswith('2012-02-07')
  dates=['2012-02-04','2012-02-06'];inferred='2012-02-06';alternatives=dates
  datebasis='Opening says Monday around 19:45 before publication 2012-02-07T02:38IST, implying 2012-02-06. Final officer quote instead says Saturday, implying 2012-02-04. Both within same government spell; frozen event-date field remains blank.'
  dateconfidence='opening_inferred_date_with_internal_weekday_conflict; bounded_government_assignment'
 assert dates, r['case_id']
 applicable={get_spell(day)['spell_id'] for day in dates};assert len(applicable)==1,(r['case_id'],dates,applicable)
 s=get_spell(dates[0]);force,authority,note=institutions.get(r['case_id'],('West Bengal police','state_police','Government incumbency is context, not evidence of instructions or responsibility for this act.'))
 source_ids=s['source_ids']+(['MHA_CAPF','MHA_ANNUAL'] if 'MHA' in authority else [])+(['RPA_28A','ECI_FORCE_MANUAL'] if 'ECI' in authority else [])
 assignments.append(dict(case_id=r['case_id'],frozen_input_event_date_ist=r['event_date_ist'],government_date_start=min(dates),government_date_end=max(dates),government_date_point_inferred=inferred,alternative_event_dates=alternatives,government_date_basis=datebasis,event_date_confidence=dateconfidence,government_assignment_robust_across_alternative_dates=True,state='West Bengal',state_chief_minister=s['chief_minister'],state_cm_party=s['cm_party'],state_government_coalition=s['government_coalition'],state_BJP_led_at_incident=s['cm_party']=='BJP',government_spell_id=s['spell_id'],government_assignment_confidence='high_conditional_on_input_date_or_documented_interval',force_or_institution=force,institutional_authority=authority,authority_note=note,political_order_or_causation_verified=False,source_ids=list(dict.fromkeys(source_ids)),source_urls=[SOURCES[k]['url'] for k in dict.fromkeys(source_ids)]))
result=dict(audit_scope='All West Bengal rows in the 41-row historical evidence catalogue; 2026 succession supplied only for plan/context and later-event mapping.',input_file='targeted_history/evidence_table.csv',input_sha256=hashlib.sha256(EVIDENCE.read_bytes()).hexdigest(),checked_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),catalogue_rows=41,west_bengal_rows=len(assignments),government_spells=spells,coalition_components_as_described_by_Assembly={'1996_elected_Left_Front':['CPI(M)','FB','CPI','RSP','SP','DSP','FB(M)','Biplabi Bangla Congress'],'2001_elected_Left_Front':['CPI(M)','FB','RSP','CPI','SP','DSP','FB(M)'],'2006_elected_Left_Front':['CPI(M)','FB','RSP','CPI','SP','FB(M)','DSP','RJD']},coalition_component_note='Historical Assembly descriptions of the alliance; not a separately audited complete cabinet membership roster.',case_assignments=assignments,assignment_counts=dict(collections.Counter(a['government_spell_id'] for a in assignments)),sources=SOURCES,limitations=['The September 22, 2012 Congress withdrawal uses original contemporaneous reporting; exact formal gazette acceptance/intraday cutoff not located. No catalogue event falls on that transition.','A resignation announcement, election result, swearing-in and administrative responsibility are different dates/concepts. We use assumption/oath transitions and retain same-day ambiguity.','State-government party at an incident location is not automatically the command authority of BSF/CISF/CRPF, a partisan order, or proof of causation.','The ECI 2023 manual explains framework; section 28A legislation predates 2021. Neither documents the specific Sitalkuchi firing command.','Original evidence CSV was not modified.'])
(ROOT/'government_audit_wb.json').write_text(json.dumps(result,indent=2,ensure_ascii=False))
md=['# West Bengal government-at-incident audit','',f"All {len(assignments)} West Bengal rows in the 41-row historical catalogue map to one government spell each. Event-date uncertainty remains separate from confidence in that government assignment. The original evidence CSV is unchanged.",'','| Effective date range | Chief minister; party | Governing arrangement |','|---|---|---|','| Through 5 Nov 2000 | Jyoti Basu; CPI(M) | Left Front |','| 6 Nov 2000–19 May 2011 | Buddhadeb Bhattacharjee; CPI(M) | Left Front |','| 20 May 2011–21 Sep 2012 | Mamata Banerjee; AITC | AITC-led ministry with Congress/INC |','| 22 Sep 2012 | Mamata Banerjee; AITC | Congress resignation/withdrawal transition day |','| 23 Sep 2012–8 May 2026 | Mamata Banerjee; AITC | AITC-led majority government; INC no longer cabinet partner |','| From 9 May 2026 | Suvendu Adhikari; BJP | BJP-led government; plan/context only here |','', 'The [official Assembly history](https://lalib.wb.gov.in/showOverview) anchors the 2000 and 2011 transitions and coalition identity. A [Parliamentary journal](https://eparlib.sansad.in/bitstream/123456789/764740/1/jpi_march_2001.pdf) corroborates the 2000 succession. CPI(M) affiliation is corroborated by party-primary biographies of [Basu](https://cpim.org/jyoti-basu/) and [Bhattacharjee](https://cpim.org/comrade-buddhadeb-bhattacharya/).','', 'Congress ministers resigned and withdrew support on 22 September 2012 according to [contemporaneous original reporting](https://www.ndtv.com/india-news/congress-ministers-resign-from-west-bengal-government-set-sights-at-cabinet-berths-499943). Formal gazette acceptance and exact intraday cutoff were not recovered; no catalogue event sits on that boundary. The [official PMO/PIB release](https://www.pib.gov.in/PressReleasePage.aspx?PRID=2259319&lang=1&reg=3) verifies Suvendu oath date; [TOI reporting](https://timesofindia.indiatimes.com/city/kolkata/journey-from-nandigram-to-writers-buildings-the-political-journey-of-suvendu-adhikari/articleshow/130970520.cms) explicitly identifies the BJP leadership.','', '## Catalogue assignments','', '| Case | CM party; coalition | Date qualification |','|---|---|---|']
for a in assignments:md.append(f"| {a['case_id']} | {a['state_chief_minister']}; {a['state_cm_party']}; {a['state_government_coalition']} | {'Canning opening implies6 Feb 2012; conflicting Saturday implies4 Feb; same coalition' if a['case_id']=='WB_2012_Canning' else a['frozen_input_event_date_ist']} |")
md+=['','Canning publication is 7 February 2012, 02:38 IST. Monday evening implies 6 February, while the final Saturday quote implies4 February. Both dates fall under Mamata/AITC with Congress; government assignment is robust even though the frozen event date remains blank.','','## Institution and election qualifications','','BSF and CISF are central forces administered through [Union MHA Police-II](https://www.mha.gov.in/en/divisionofmha/police-ii-division), also identified in the [MHA annual report](https://www.mha.gov.in/sites/default/files/AnnualreportEnglish_04102023.pdf). State-party labels alone do not establish who commanded a central-force incident. CRPF/state-police joint operations require separate agency coding. Dum Dum is correctional administration rather than a street-police operation.','','For election duty, [section 28A](https://www.indiacode.nic.in/bitstream/123456789/1941/1/195143.pdf) places designated officers under ECI election supervision. The [ECI force-deployment manual](https://www.eci.gov.in/eci-backend/public/api/download?url=LMAhAK6sOPBp%2FNFF0iRfXbEB1EVSLT41NNLRjYNJJP1KivrUxbfqkDatmHy12e%2FzVx8fLfn2ReU7TfrqYobgIvZ0n19tFMJzYNUMlQdr0LR9wv8%2B5nXgMo0aziJ0WKXcD2mjzPfzEgKRfE3Jice0BpSrPmQz9vt2aDMViYDfJ9IM%2F2fqtXgeR74oE38CYbCb) explains roles shared across ECI, MHA and state/district functionaries. This 2023 manual is framework evidence, not a record of the 2021 Sitalkuchi firing order. Mamata/AITC was the state government on 10 April 2021; CISF was the reported firing force. Neither fact establishes a partisan order or causal responsibility.','','Exact sources, per-case confidence, date intervals and authority notes are in `government_audit_wb.json`.']
(ROOT/'government_audit_wb.md').write_text('\n'.join(md)+'\n')
print(json.dumps({'WB_rows':len(assignments),'assignments':result['assignment_counts'],'original_CSV_unchanged':hashlib.sha256(EVIDENCE.read_bytes()).hexdigest()==result['input_sha256']}))
